<?php
require_once __DIR__.'/includes/panel_helpers.php';
$rolId=exigirRol([1,2]);
require_once __DIR__.'/../config/database.php';
$busqueda=trim((string)($_GET['q']??''));$metodo=(string)($_GET['metodo']??'todos');$estado=(string)($_GET['estado']??'pagado');
if(!in_array($metodo,['todos','efectivo','qr','tarjeta','transferencia'],true))$metodo='todos';
if(!in_array($estado,['todos','pagado','anulado'],true))$estado='pagado';
$pagos=[];$pendientes=[];$resumen=['total'=>0,'operaciones'=>0,'efectivo'=>0,'qr'=>0,'tarjeta'=>0,'transferencia'=>0];$error=false;
try{
    $pdo=conectarBD();
    $r=$pdo->query("SELECT COALESCE(SUM(monto) FILTER(WHERE estado='pagado'),0) total,COUNT(*) FILTER(WHERE estado='pagado') operaciones,COALESCE(SUM(monto) FILTER(WHERE estado='pagado' AND metodo='efectivo'),0) efectivo,COALESCE(SUM(monto) FILTER(WHERE estado='pagado' AND metodo='qr'),0) qr,COALESCE(SUM(monto) FILTER(WHERE estado='pagado' AND metodo='tarjeta'),0) tarjeta,COALESCE(SUM(monto) FILTER(WHERE estado='pagado' AND metodo='transferencia'),0) transferencia FROM pagos WHERE pagado_at::date=CURRENT_DATE")->fetch();if($r)$resumen=$r;
    $cond=['1=1'];$params=[];
    if($metodo!=='todos'){$cond[]='pg.metodo=:metodo';$params['metodo']=$metodo;}
    if($estado!=='todos'){$cond[]='pg.estado=:estado';$params['estado']=$estado;}
    if($busqueda!==''){$cond[]="(LOWER(pg.codigo_pago) LIKE :q OR LOWER(c.codigo_cita) LIKE :q OR LOWER(p.nombres||' '||p.apellidos) LIKE :q OR LOWER(COALESCE(pg.referencia,'')) LIKE :q)";$params['q']='%'.mb_strtolower($busqueda).'%';}
    $sql="SELECT pg.*,c.codigo_cita,c.inicio,p.nombres||' '||p.apellidos paciente,u.nombre registrado_por_nombre FROM pagos pg JOIN citas c ON c.id=pg.cita_id JOIN pacientes p ON p.id=pg.paciente_id JOIN usuarios u ON u.id=pg.registrado_por WHERE ".implode(' AND ',$cond).' ORDER BY pg.pagado_at DESC,pg.id DESC LIMIT 150';
    $s=$pdo->prepare($sql);$s->execute($params);$pagos=$s->fetchAll();
    $pendientes=$pdo->query("SELECT c.id,c.codigo_cita,c.inicio,p.nombres||' '||p.apellidos paciente,e.nombre especialidad FROM citas c JOIN pacientes p ON p.id=c.paciente_id JOIN especialidades e ON e.id=c.especialidad_id WHERE c.estado IN ('confirmada','completada') AND NOT EXISTS(SELECT 1 FROM pagos pg WHERE pg.cita_id=c.id AND pg.estado='pagado') ORDER BY c.inicio DESC LIMIT 8")->fetchAll();
}catch(Throwable $e){error_log($e->getMessage());$error=true;}
require_once __DIR__.'/includes/layout.php';renderSidebar('pagos');
?>
<div class="doctor-page-heading"><div class="section-title"><span class="page-emblem green"><?= icono('atendida') ?></span><div><span class="doctor-eyebrow">Recepción y caja</span><h1>Pagos</h1><p>Registra cobros, consulta movimientos y controla la caja diaria.</p></div></div><?php if($rolId===1):?><a class="btn btn-secondary" href="configurar_metodos_pago.php">Configurar QR bancario</a><?php endif;?></div>
<?php if($error):?><div class="alert alert-error">El módulo todavía no está disponible. Aplica la migración de pagos e inténtalo nuevamente.</div><?php else:?>
<div class="stats-grid payment-stats"><?php foreach([['Cobrado hoy','total','green','atendida','Bs '],['Operaciones','operaciones','blue','historial',''],['Efectivo','efectivo','gold','reloj','Bs '],['QR y transferencias','digital','purple','agenda','Bs ']] as [$titulo,$clave,$color,$icono,$prefijo]):$valor=$clave==='digital'?(float)$resumen['qr']+(float)$resumen['transferencia']:(float)$resumen[$clave];?><article class="stat-card"><span class="stat-icon <?= $color ?> illustrated-icon"><?= icono($icono) ?></span><div class="stat-info"><p class="stat-label"><?= $titulo ?></p><strong class="stat-value"><?= $prefijo.($clave==='operaciones'?number_format($valor):number_format($valor,2)) ?></strong></div></article><?php endforeach;?></div>
<div class="reception-payment-grid"><section class="card"><div class="card-header"><div><h2 class="card-title">Citas pendientes de cobro</h2><p class="card-subtitle">Confirmadas o completadas sin un pago activo</p></div></div><div class="card-body flush"><?php if(!$pendientes):?><div class="empty-state">No hay citas pendientes de cobro.</div><?php else:?><div class="table-container"><table class="table"><thead><tr><th>Cita</th><th>Paciente</th><th>Fecha</th><th>Especialidad</th><th></th></tr></thead><tbody><?php foreach($pendientes as $cita):?><tr><td><?= h($cita['codigo_cita']) ?></td><td><?= h($cita['paciente']) ?></td><td><?= date('d/m/Y H:i',strtotime($cita['inicio'])) ?></td><td><?= h($cita['especialidad']) ?></td><td><a class="btn btn-sm btn-primary" href="registrar_pago.php?cita_id=<?= (int)$cita['id'] ?>">Registrar pago</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></section><aside class="card payment-summary"><div class="card-header"><h2 class="card-title">Caja de hoy</h2></div><div class="card-body"><div><span>Efectivo</span><strong>Bs <?= number_format((float)$resumen['efectivo'],2) ?></strong></div><div><span>QR</span><strong>Bs <?= number_format((float)$resumen['qr'],2) ?></strong></div><div><span>Tarjeta</span><strong>Bs <?= number_format((float)$resumen['tarjeta'],2) ?></strong></div><div><span>Transferencia</span><strong>Bs <?= number_format((float)$resumen['transferencia'],2) ?></strong></div><div class="payment-total"><span>Total</span><strong>Bs <?= number_format((float)$resumen['total'],2) ?></strong></div></div></aside></div>
<section class="card"><div class="card-header"><div><h2 class="card-title">Historial de pagos</h2><p class="card-subtitle">Últimos 150 movimientos</p></div></div><div class="card-body"><form class="search-bar payment-filters" method="GET"><div class="search-input-wrapper"><?= icono('buscar') ?><input class="form-input" type="search" name="q" value="<?= h($busqueda) ?>" placeholder="Paciente, cita, pago o referencia"></div><select class="form-select" name="metodo"><option value="todos">Todos los métodos</option><?php foreach(['efectivo'=>'Efectivo','qr'=>'QR','tarjeta'=>'Tarjeta','transferencia'=>'Transferencia'] as $v=>$n):?><option value="<?= $v ?>" <?= $metodo===$v?'selected':'' ?>><?= $n ?></option><?php endforeach;?></select><select class="form-select" name="estado"><option value="todos">Todos los estados</option><option value="pagado" <?= $estado==='pagado'?'selected':'' ?>>Pagados</option><option value="anulado" <?= $estado==='anulado'?'selected':'' ?>>Anulados</option></select><button class="btn btn-secondary" type="submit">Filtrar</button></form></div><div class="card-body flush"><?php if(!$pagos):?><div class="empty-state">No se encontraron pagos.</div><?php else:?><div class="table-container"><table class="table"><thead><tr><th>Comprobante</th><th>Paciente</th><th>Fecha</th><th>Método</th><th>Monto</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($pagos as $pago):?><tr><td><strong><?= h($pago['codigo_pago']) ?></strong><small class="table-secondary-text"><?= h($pago['codigo_cita']) ?></small></td><td><?= h($pago['paciente']) ?></td><td><?= date('d/m/Y H:i',strtotime($pago['pagado_at'])) ?></td><td><?= h(ucfirst($pago['metodo'])) ?></td><td><strong>Bs <?= number_format((float)$pago['monto'],2) ?></strong></td><td><span class="badge badge-<?= $pago['estado']==='pagado'?'success':'danger' ?>"><?= h(ucfirst($pago['estado'])) ?></span></td><td><div class="action-row"><a class="btn btn-sm btn-secondary" href="recibo_pago.php?id=<?= (int)$pago['id'] ?>" target="_blank">Recibo</a><?php if($rolId===1&&$pago['estado']==='pagado'):?><a class="btn btn-sm patient-cancel-button" href="anular_pago.php?id=<?= (int)$pago['id'] ?>">Anular</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></section>
<?php endif;renderFooter();?>
